contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(string calldata name_, string calldata tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // bound lengths to avoid extreme gas or storage effects
        require(bytes(name_).length < 200);
        require(bytes(tokenURI).length < 200);

        // observe before-state
        uint256 beforeCount = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;

        bool reverted;
        // perform the state-changing call as a top-level statement and observe revert
        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-state
        uint256 afterCount = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;

        // Either the call reverted and count unchanged, or it succeeded and count increased by exactly 1
        assert((reverted && afterCount == beforeCount) || (!reverted && afterCount == beforeCount + 1));
    }

    receive() external payable {}
}

